// РЕКОНСИЛИАЦИЯ И КЛЮЧИ: баг с key={index}
function BadList({ items, onToggle }) {
  return items.map((it, i) => (
    // индекс = позиция: при удалении первой строки React «переписывает»
    // состояние каждой следующей строки, потому что позиции сместились
    <li key={i}>
      <Checkbox checked={it.done} onChange={() => onToggle(it.id)} />
      {it.title}
    </li>
  ));
}

function GoodList({ items, onToggle }) {
  return items.map((it) => (
    // стабильная идентичность: React сопоставляет старый узел с новым по id
    <li key={it.id}>
      <Checkbox checked={it.done} onChange={() => onToggle(it.id)} />
      {it.title}
    </li>
  ));
}
