}

// Загрузка с отменой: старый ответ не перетирает новый
function useOrders(filter) {
  const [state, setState] = useState({ status: 'idle', data: [], error: null });

  useEffect(() => {
    const controller = new AbortController();
    setState((s) => ({ ...s, status: 'loading' }));        // сразу показываем скелетон
    fetch(`/api/orders?status=${encodeURIComponent(filter)}`, { signal: controller.signal })
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(`HTTP ${r.status}`))))
      .then((data) => setState({ status: 'ready', data, error: null }))
      .catch((e) => {
        if (e.name === 'AbortError') return;               // наша отмена — не ошибка
        setState({ status: 'error', data: [], error: e });
      });
    return () => controller.abort();                       // cleanup при смене фильтра/размонтировании
  }, [filter]);                                            // зависимость — единственная причина перезапуска

  const retry = () => setState((s) => ({ ...s, status: 'idle' })); // триггер перезапуска
  return { ...state, retry };
}

// Дебаунс ввода в значение фильтра (без лишних запросов на каждую букву)
function useDebouncedValue(value, ms = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), ms);
    return () => clearTimeout(t);
  }, [value, ms]);
  return debounced;
}

// Свой хук: измерение элемента + debounce — инкапсулируем состояние и эффект
function useElementWidth() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return [ref, width];
}

// useReducer: переходы формы в одном месте, легче тестировать
const initialForm = { status: 'editing', values: {}, errors: {}, savedAt: null };
function formReducer(state, action) {
  switch (action.type) {
    case 'change':   return { ...state, values: { ...state.values, ...action.patch } };
    case 'validate': return { ...state, errors: action.errors, status: 'editing' };
    case 'saving':   return { ...state, status: 'saving', errors: {} };
    case 'saved':    return { ...state, status: 'editing', savedAt: action.at };
    case 'failed':   return { ...state, status: 'editing', errors: action.errors };
    default: return state;
  }
}

