// Error boundary: класс — потому что перехват ошибок рендера есть только у него
class ErrorBoundary extends React.Component {
  state = { error: null };
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { reportToSentry(error, info); }   // лог — обязательно
  render() {
    if (this.state.error) {
      return (
        <div role="alert">
          <h3>Секция временно недоступна</h3>
          <button onClick={() => this.setState({ error: null })}>Повторить</button>
        </div>
      );
    }
    return this.props.children;
  }
}

// Оптимистичная отметка задачи с гарантированным откатом
function useToggleTask() {
  const [pending, setPending] = useState(new Set());
  const toggle = async (task) => {
    const prev = task.done;
    setPending((p) => new Set(p).add(task.id));
    cache.set(task.id, { ...task, done: !prev });          // 1) локально (мгновенный UI)
    try {
      await api.patch(`/tasks/${task.id}`, { done: !prev });
    } catch (e) {
      cache.set(task.id, task);                            // 2) откат при ошибке
      toast.error('Не удалось сохранить, вернули как было');
    } finally {
      setPending((p) => { const n = new Set(p); n.delete(task.id); return n; });
    }
  };
  return { toggle, pending };
}

// --- Redux Toolkit: slice с асинхронной операцией (кратко) ---
import { configureStore, createSlice, createAsyncThunk } from '@reduxjs/toolkit';

export const loadOrders = createAsyncThunk('orders/load', async (_, { rejectWithValue }) => {
  try {
    const res = await fetch('/api/orders');
    if (!res.ok) throw new Error(String(res.status));
    return await res.json();
  } catch (e) {
    return rejectWithValue(e.message);            // ошибка -> rejected с payload
  }
});

const ordersSlice = createSlice({
  name: 'orders',
  initialState: { items: [], status: 'idle', error: null },
  reducers: {
    markShipped(state, action) {
      const o = state.items.find((x) => x.id === action.payload);   // Immer: «мутация» безопасна
      if (o) o.status = 'shipped';
    },
  },
  extraReducers: (b) => b
    .addCase(loadOrders.pending, (s) => { s.status = 'loading'; s.error = null; })
    .addCase(loadOrders.fulfilled, (s, a) => { s.status = 'ready'; s.items = a.payload; })
    .addCase(loadOrders.rejected, (s, a) => { s.status = 'error'; s.error = a.payload; }),
});

export const { markShipped } = ordersSlice.actions;
export const store = configureStore({ reducer: { orders: ordersSlice.reducer } });

// --- RTK Query: данные вместо ручных fetch/useEffect ---
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const ordersApi = createApi({
  reducerPath: 'ordersApi',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  tagTypes: ['Order'],
  endpoints: (b) => ({
    getOrders: b.query({ query: (status = '') => `/orders?status=${status}`, providesTags: ['Order'] }),
    shipOrder: b.mutation({
      query: (id) => ({ url: `/orders/${id}/ship`, method: 'POST' }),
      invalidatesTags: ['Order'],                 // после мутации — фоновое обновление списка
    }),
  }),
});

function OrdersPage() {
